package com.cpf.integration.tcp;import java.time.*;import java.util.*;import java.util.concurrent.*;
public final class CpfTcpCorrelationRegistry {private final ConcurrentHashMap<String,Pending> pending=new ConcurrentHashMap<>();private final ConcurrentLinkedQueue<Orphan> orphans=new ConcurrentLinkedQueue<>();private final int maxPending,maxOrphans;public CpfTcpCorrelationRegistry(int p,int o){if(p<1||o<1)throw new IllegalArgumentException();maxPending=p;maxOrphans=o;}public CompletableFuture<byte[]> register(String id,Duration timeout,Clock clock){if(pending.size()>=maxPending)throw new IllegalStateException("TCP pending limit reached");var f=new CompletableFuture<byte[]>();var x=new Pending(f,Instant.now(clock).plus(timeout));if(pending.putIfAbsent(id,x)!=null)throw new IllegalStateException("duplicate correlation: "+id);return f;}public boolean complete(String id,byte[] response,Clock clock){var x=pending.remove(id);if(x==null){while(orphans.size()>=maxOrphans)orphans.poll();orphans.add(new Orphan(id,response.clone(),Instant.now(clock)));return false;}x.future.complete(response.clone());return true;}public int expire(Clock clock){int n=0;Instant now=Instant.now(clock);for(var e:pending.entrySet())if(!e.getValue().deadline.isAfter(now)&&pending.remove(e.getKey(),e.getValue())){e.getValue().future.completeExceptionally(new TimeoutException(e.getKey()));n++;}return n;}public List<Orphan> orphans(){return List.copyOf(orphans);}public int pendingCount(){return pending.size();}private record Pending(CompletableFuture<byte[]> future,Instant deadline){}public record Orphan(String correlationId,byte[] response,Instant receivedAt){public Orphan{response=response.clone();}public byte[] response(){return response.clone();}}}
